-- Live patch: replace the 4 youth drill_blocks rows with the new
-- stroke-specific content (forehand/backhand/volley/serve/footwork/game).
-- Safe to run directly -- only updates existing rows, no schema change.

update public.drill_blocks set content = '{"name": "Red Starter", "blurb": "Ball tracking, balance, catching, and first taps with the racquet — no rallying pressure yet, just games.", "badges": ["Bounce & Catch", "Ready-Position Freeze Game", "Balloon Volley Rally", "Rolling-Ball Scoop Pickup", "Underhand Toss to a Target", "Racquet Balance Walk"], "forehand": "Grip check (''shake hands'' with the racquet) plus bounce-and-catch on the strings to feel the hitting surface before any real swing; no live feed yet.", "backhand": "Two-hand ''hammer'' grip setup — practice turning to the non-dominant side and tapping a stationary ball off a cone with both hands together.", "volley": "Racquet-face awareness at the net through catch-and-tap games, holding the racquet like a frying pan to feel a flat surface close to the body.", "serve": "Underhand toss-and-tap into the service box from a shortened baseline, focusing only on tossing the ball out in front — no swing yet.", "footwork": "Bouncy ''ready position'' freeze games on a clap or whistle, plus animal-walk footwork patterns (bear crawl, crab walk) to and from the net.", "game": "Balloon volleys and bounce-and-catch relay races — no scoring yet, just fun repetition of racquet-to-ball contact."}'::jsonb where pathway = 'youth' and youth_stage = 'red_starter';
update public.drill_blocks set content = '{"name": "Red Rally", "blurb": "First real racquet-and-ball rallying on the mini (36-ft) red-ball court, plus first serves.", "badges": ["Self-Bounce Rally (3 hits)", "Forehand Contact Point", "Backhand Contact Point", "Sideways Shuffle Steps", "Mini-Court Feed Rally (5 balls)", "Drop-and-Hit Serve"], "forehand": "Self-drop forehand rally reps on the mini court — 3 in a row self-fed, then a coach feed — checking grip and a simple low-to-high starter swing.", "backhand": "Two-handed backhand off a gentle coach feed on the mini court, matching the forehand''s target and rep count to build the weaker wing evenly.", "volley": "Close-range forehand and backhand volley taps off a soft feed just inside the service line, using a ''catch it with the strings'' cue.", "serve": "Drop-and-hit serve into a marked service box from the mini-court baseline, introducing a continental-ish grip for the first time.", "footwork": "Sideways shuffle steps (feet never crossing) to reach a ball fed left or right, plus a split-step cue timed to the feeder''s contact.", "game": "Mini-court rally games — keep it in the court 3, then 5, then 7 times in a row as a team; simple mini-matches with underhand serves allowed."}'::jsonb where pathway = 'youth' and youth_stage = 'red_rally';
update public.drill_blocks set content = '{"name": "Red Game Player", "blurb": "Real mini-tennis scoring, court positioning, and the first lessons in sportsmanship.", "badges": ["Count-to-7 Scoring", "Two-Bounce Rule Understanding", "Court Position Awareness", "Doubles Teamwork Game", "Good-Sport Handshake", "Call-Your-Own-Line Honesty"], "forehand": "Full-swing forehand on the red court aimed at a cone or hoop target, introducing the idea of cross-court versus down-the-line direction.", "backhand": "Full two-handed backhand matching the forehand''s target work, plus a first look at a one-handed backhand slice block for a fast ball.", "volley": "Forehand and backhand volley points started from mid-court, closing the last few steps to the net after a partner or coach feed.", "serve": "Full service motion (bounce, toss, swing) into alternating deuce/ad boxes, introducing the idea of a first serve and a second serve.", "footwork": "Recovery-step games — moving back to the middle of the court after every shot, checked with a coach call or a cone marker on the baseline.", "game": "Real scoring mini-matches (game/set format) on the full red court, plus doubles positioning basics and a good-sport handshake routine after every game."}'::jsonb where pathway = 'youth' and youth_stage = 'red_game_player';
update public.drill_blocks set content = '{"name": "Orange Ready", "blurb": "Stretching rallies longer, first shot-selection ideas, and getting comfortable on the bigger orange-ball court.", "badges": ["Sustained Rally (5+ both sides)", "Move-Up on a Short Ball", "Stay-Back on a Deep Ball", "Play a Mini-Tournament", "Orange-Ball Comfort Rally", "Serve Into the Box (3 in a row)"], "forehand": "Forehand on the orange (78-ft) court with more running room, introducing a bit of topspin shape (low-to-high swing) to clear a deeper target.", "backhand": "Two-handed backhand on the orange court with the same shape introduction, plus continued one-handed slice reps for defense on a fast ball.", "volley": "Forehand and backhand volleys on the orange-court net, working a short punch motion for real depth and direction, not just contact.", "serve": "Serve on the orange court working toward 3-4 in a row inside the box from both the deuce and ad sides, using a full-height service motion.", "footwork": "Split-step timing off a live feed plus lateral movement drills using the full width of the orange court.", "game": "Mini-tournament format matches on the orange court with real scoring and serve rotation, building toward the season''s badge ceremony."}'::jsonb where pathway = 'youth' and youth_stage = 'orange_ready';
